def find_middle(input_str):
    if not isinstance(input_str, str):
        return -1

    digits = [int(char) for char in input_str if char.isdigit()]
    if not digits:
        return -1

    product = 1
    for digit in digits:
        product *= digit

    product_str = str(product)
    if len(product_str) % 2 == 1:
        return int(product_str[(len(product_str) - 1) // 2])
    else:
        return int(product_str[(len(product_str) - 2) // 2:(len(product_str)) // 2])

# Example usage:
# print(find_middle('s7d8jd9'))  # Output: 0
# print(find_middle('1563'))     # Output: 56
# print(find_middle('2016'))     # Output: 1
